// Detail-page content for each solution, written from what the product actually does.
// Keyed by the ids in data/solutions.ts. Nothing here should describe a feature the
// product does not have: check it against the product before adding a line.

export interface SolutionHighlight {
  title: string
  text: string
  // Static SVG for the tab view panel or bento item (see coversLayout); trusted markup from this file.
  visual?: string
  // Icon in the tab view's tab button; defaults to a check mark.
  icon?: 'shield' | 'calendar-clock' | 'layout-grid' | 'bar-chart'
}

export interface SolutionDetail {
  // Eyebrow and <h1> of the page
  eyebrow: string
  title: string
  intro: string
  // Short line on this module's "Works with" card on other solution pages; defaults to the
  // first sentence of the intro.
  summary?: string
  highlights: readonly SolutionHighlight[]
  // 'tabs' (interactive tab view) or 'bento' (bento grid) instead of the default card grid.
  coversLayout?: 'tabs' | 'bento'
  // With 'bento': swap the big item to the right and the stacked pair to the left at >= 1024px.
  coversMirror?: boolean
  // Who it is written for
  audience: readonly string[]
  // Solution ids this one works with (shown as "Connected modules")
  related: readonly string[]
  // Operations only. 'expand': "Choose how you fly" as expanding panels, with each child's
  // panel copy and visual keyed by child id.
  childLayout?: 'expand'
  childPanels?: Readonly<Record<string, { teaser: string, description: string, visual: string }>>
  // 'list': "Works with" as a list instead of the card grid. With worksWithIntro the left
  // column is "Works with" + that line (no "Who it's for"); without it, "Who it's for" stays
  // on the left. relatedText overrides each related module's short description.
  worksWithLayout?: 'list'
  worksWithIntro?: string
  relatedText?: Readonly<Record<string, string>>
  // SEO
  seoTitle: string
  seoDescription: string
  keywords: readonly string[]
}

